import { createContext, Dispatch, ReactNode, useContext, useReducer } from 'react';

type State = { count: number };
type Action = { type: 'inc' } | { type: 'dec' };

const reducer = (s: State, a: Action): State => {
  switch (a.type) {
    case 'inc':
      return { count: s.count + 1 };
    case 'dec':
      return { count: s.count - 1 };
  }
};

const StateCtx = createContext<State | null>(null);
const DispatchCtx = createContext<Dispatch<Action> | null>(null);

export function CounterProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(reducer, { count: 0 });
  return (
    <StateCtx.Provider value={state}>
      <DispatchCtx.Provider value={dispatch}>{children}</DispatchCtx.Provider>
    </StateCtx.Provider>
  );
}

export function useCounterState(): State {
  const ctx = useContext(StateCtx);
  if (!ctx) throw new Error('useCounterState outside provider');
  return ctx;
}

export function useCounterDispatch(): Dispatch<Action> {
  const ctx = useContext(DispatchCtx);
  if (!ctx) throw new Error('useCounterDispatch outside provider');
  return ctx;
}
